function isPointInsideRectangle(point: { x: number; y: number }, rectangle: { left: number; top: number; width: number; height: number }): boolean {
  return point.x >= rectangle.left && point.x <= rectangle.left + rectangle.width &&
         point.y >= rectangle.top && point.y <= rectangle.top + rectangle.height;
}

function isRectangleInsideRectangle(rectangleA: { left: number; top: number; width: number; height: number }, rectangleB: { left: number; top: number; width: number; height: number }): boolean {
  return isPointInsideRectangle({ x: rectangleA.left, y: rectangleA.top }, rectangleB) &&
         isPointInsideRectangle({ x: rectangleA.left + rectangleA.width, y: rectangleA.top }, rectangleB) &&
         isPointInsideRectangle({ x: rectangleA.left, y: rectangleA.top + rectangleA.height }, rectangleB) &&
         isPointInsideRectangle({ x: rectangleA.left + rectangleA.width, y: rectangleA.top + rectangleA.height }, rectangleB);
}

function main(): null {
  const rectangleA = { left: 0, top: 0, width: 4, height: 4 };
  const rectangleB = { left: 2, top: 2, width: 3, height: 3 };

  if (isRectangleInsideRectangle(rectangleA, rectangleB)) {
    console.log("collision-aabb-1:ok");
  } else {
    throw { code: "CHECK_FAILED", message: "unexpected collision" };
  }

  return null;
}

