import * as console from "std/console";

function isAlive(cell: boolean): boolean {
  return cell;
}

function countNeighbors(grid: boolean[][], row: number, col: number): int {
  let count = 0;
  for (let i = -1; i <= 1; i++) {
    for (let j = -1; j <= 1; j++) {
      if (i === 0 && j === 0) continue;
      const newRow = row + i;
      const newCol = col + j;
      if (newRow >= 0 && newRow < grid.length && newCol >= 0 && newCol < grid[newRow].length) {
        count += grid[newRow][newCol] ? 1 : 0;
      }
    }
  }
  return count;
}

function updateCell(grid: boolean[][], row: number, col: number): void {
  const alive = isAlive(grid[row][col]);
  const neighbors = countNeighbors(grid, row, col);
  if (alive && (neighbors < 2 || neighbors > 3)) {
    grid[row][col] = false;
  } else if (!alive && neighbors === 3) {
    grid[row][col] = true;
  }
}

function simulateLife(grid: boolean[][]): void {
  const newGrid = Array.from({ length: grid.length }, () => Array.from({ length: grid[0].length }, () => false));
  for (let row = 0; row < grid.length; row++) {
    for (let col = 0; col < grid[row].length; col++) {
      updateCell(newGrid, row, col);
    }
  }
  grid.forEach((row, i) => {
    newGrid[i] = row.map((cell, j) => cell ? true : false);
  });
}

function main(): null {
  const initialGrid: boolean[][] = [
    [true, false, false],
    [false, true, false],
    [false, false, true]
  ];

  simulateLife(initialGrid);

  console.log("cellular-automaton-1:ok");
  return null;
}

